return ['domain'=>'tranzly','plural-forms'=>'nplurals=3; plural=(((((((0 == 0)) && ((((n == 0)) == 0))) && (((n % 1000000) == 0))) && ((0 == 0))) || ((((0 >= 0 && 0 <= 5)) == 0))) ? 1 : ((n == 1)) ? 0 : 2);','language'=>'es_ES','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'WordPress multilingüe, una entrada por idioma: traducciones vinculadas de entradas, páginas, categorías, texto multimedia, widgets y el título del sitio, con sus antiguas traducciones de Tranzly importadas.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Proveedores de IA','The makers of ChatGPT. A good all-rounder.'=>'Los creadores de ChatGPT. Un buen todoterreno.','The makers of Claude. Strong at writing and careful reasoning.'=>'Los creadores de Claude. Fuertes en la escritura y con un razonamiento cuidadoso.','Google\'s Gemini models. Fast and inexpensive.'=>'Los modelos Gemini de Google. Rápidos y económicos.','A European AI company with fast, inexpensive models.'=>'Una empresa europea de IA con modelos rápidos y económicos.','Low-cost models that are good at writing and code.'=>'Modelos de bajo coste buenos para la escritura y el código.','One key for models from many different providers.'=>'Una sola clave para modelos de muchos proveedores diferentes.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Cualquier servicio que funcione como la API de OpenAI, incluido un modelo que se ejecute en su propia computadora o servidor.','General (used when nothing more specific is set)'=>'General (se usa cuando no se establece nada más específico)','Writing and rewriting'=>'Escritura y reescritura','Translation'=>'Traducción','Code and CSS'=>'Código y CSS','Sorry, you are not allowed to access this page.'=>'Lo sentimos, no tiene permitido acceder a esta página.','These settings are shared by every plugin that uses them: %s.'=>'Estos ajustes son compartidos por todos los complementos que los utilizan: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Sus claves se cifran en la base de datos de este sitio y solo se envían al proveedor que haya elegido, nunca a nosotros.','Step 1 of 2: choose an AI provider'=>'Paso 1 de 2: elige un proveedor de IA','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Usted aporta su propia clave, por lo que paga directamente al proveedor por lo que consume. ¿No está seguro? Cualquiera de estas opciones funciona bien; puede añadir más más adelante.','Next'=>'Siguiente','Step 2 of 2: connect %s'=>'Paso 2 de 2: conectar %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Introduzca la dirección de su servicio compatible con OpenAI, terminada en /v1. Solo se necesita una clave si el servicio la solicita.','Open %s and sign in (or create a free account).'=>'Abra %s e inicie sesión (o cree una cuenta gratuita).','the %s API keys page'=>'la página de claves de API de %s','Create a new key and copy it.'=>'Cree una nueva clave y cópiela.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Péguelo a continuación y presione "Guardar y probar". Enviamos una pequeña solicitud para comprobar que funciona.','Most providers need a little credit on the account before a key works: %s.'=>'La mayoría de los proveedores necesitan un pequeño saldo en la cuenta para que una clave funcione: %s.','add credit'=>'añadir crédito','← Choose a different provider'=>'← Elegir un proveedor diferente','Address'=>'Dirección','Saved key ends in …%s — paste a new one to replace it'=>'La clave guardada termina en …%s; pegue una nueva para reemplazarla','Key (optional)'=>'Clave (opcional)','API key'=>'Clave de API','Save and test'=>'Guardar y probar','Providers'=>'Proveedores','Provider'=>'Proveedor','Status'=>'Estado','Key'=>'Clave','Get a key'=>'Obtener una clave','Test'=>'Probar','Remove'=>'Eliminar','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Guardado con una versión de plugin más reciente: actualice este plugin o introduzca la clave de nuevo.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'La clave guardada ya no se puede abrir (las claves de seguridad del sitio han cambiado). Introdúzcala de nuevo.','Not connected'=>'No conectado','Connected — last test passed %s'=>'Conectado — última prueba superada %s','Last test failed: %s'=>'Última prueba fallida: %s','Connected — not tested yet'=>'Conectado — pendiente de prueba','Which model to use'=>'¿Qué modelo utilizar','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ señala nuestra recomendación para esa tarea. La lista incluye todos los modelos que su clave puede usar, obtenidos en tiempo real del proveedor.','— Recommended for the provider —'=>'— Recomendado para el proveedor —','Save models'=>'Guardar modelos','Refresh the model lists from the providers'=>'Actualizar las listas de modelos de los proveedores','best quality'=>'mejor calidad','lowest cost'=>'menor coste','fastest'=>'más rápido','Add a model yourself'=>'Añadir un modelo usted mismo','A model came out today? Paste its exact name to use it straight away.'=>'¿Ha salido un modelo hoy? Pega su nombre exacto para usarlo de inmediato.','Model name'=>'Nombre del modelo','Add model'=>'Añadir modelo','Recommended models list'=>'Lista de modelos recomendados','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'No se pudo verificar la lista de modelos recomendados, por lo que no se muestran recomendaciones. Reinstale el plugin o active las actualizaciones diarias a continuación.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'La lista en uso se publicó el %s. Cada actualización de plugin incluye una nueva.','Also check Zinn Digital® once a day for an updated list.'=>'Consulte también Zinn Digital® una vez al día para ver la lista actualizada.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Solo se envía una solicitud de descarga simple: ninguna clave, ninguna dirección de sitio, nada sobre su contenido. La lista está firmada y cualquier lista que no supere la comprobación de la firma se ignora.','Last checked %1$s: %2$s.'=>'Última comprobación %1$s: %2$s.','Save, and check now if turned on'=>'Guardar y comprobar ahora si está activado','a newer list was installed'=>'se instaló una lista más nueva','already up to date'=>'ya actualizado','the download failed the signature check and was ignored'=>'la descarga falló en la verificación de la firma y fue descartada','Zinn Digital® could not be reached; the current list stays in use'=>'No se pudo contactar con Zinn Digital®; la lista actual sigue en uso','turned off'=>'desactivado','Open'=>'Abrir','Check their status page'=>'Consultar su página de estado','Open your billing page'=>'Abra su página de facturación','Open your API keys page'=>'Abra su página de claves de API','Open the AI settings'=>'Abrir la configuración de IA','Sorry, you are not allowed to do that.'=>'Lo siento, no tiene permitido hacer eso.','Unknown provider.'=>'Proveedor desconocido.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Ingrese la dirección de su servicio, por ejemplo http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Eso no parece una clave de API. Cópiela de nuevo, sin espacios.','Paste your API key first.'=>'Pegue primero su clave de API.','Key removed.'=>'Clave eliminada.','Models saved.'=>'Modelos guardados.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Introduzca el nombre exacto del modelo, por ejemplo, tal como aparece en la documentación del proveedor.','Added %s. Choose it under "Which model to use".'=>'Añadido %s. Elíjalo en "Qué modelo utilizar".','Model removed.'=>'Modelo eliminado.','Daily updates are off. The list that came with the plugin is used.'=>'Las actualizaciones diarias están desactivadas. Se utiliza la lista que venía con el complemento.','Checked: %s.'=>'Marcado: %s.','Model lists refreshed.'=>'Listas de modelos actualizadas.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Su clave de IA fue guardada por una versión más reciente de uno de sus complementos. Actualice este complemento o introduzca la clave nuevamente en la configuración de IA.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Su clave de IA guardada ya no se puede abrir (las claves de seguridad del sitio han cambiado). Introdúzcala de nuevo en la configuración de IA.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'La inteligencia artificial no está configurada aún. Añade una clave para un proveedor de IA en la configuración de IA.','No model is chosen for this task. Pick one in the AI settings.'=>'No hay ningún modelo seleccionado para esta tarea. Elige uno en la configuración de IA.','That AI provider is not supported by this version of the plugin.'=>'Ese proveedor de inteligencia artificial no es compatible con esta versión del complemento.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Este sitio no ha podido comunicarse con su servicio de IA. Compruebe que esté en funcionamiento y que su dirección sea accesible desde su servidor web (un servicio en su propia computadora no es accesible desde un sitio alojado).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Este sitio no pudo comunicarse con %s. Consulte su página de estado; si está en línea, es posible que su proveedor de alojamiento esté bloqueando las conexiones salientes o que la dirección sea incorrecta.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s indica que su cuenta no tiene crédito o cuota disponible. Añada crédito o aumente su límite en su cuenta con ellos y vuelva a intentarlo.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s no ha aceptado su clave. Es posible que esté mal escrita, haya sido revocada o haya caducado. Cree una clave nueva y péguela aquí.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ha rechazado esta solicitud para su clave. Es posible que la clave no tenga acceso a este modelo o función, o que su cuenta deba ser verificada.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'El modelo "%1$s" no está disponible en %2$s para su clave. Elija otro modelo en la configuración de IA.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Su plan %2$s no incluye el modelo "%1$s". Elija otro modelo en la configuración de IA o actualice su plan con ellos.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s está limitando la velocidad a la que su clave puede enviar solicitudes. Espere un minuto y vuelva a intentarlo, o aumente su límite de tasa con ellos.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s está teniendo problemas en este momento (una caída o sobrecarga por su parte). Sus ajustes están correctos. Vuelva a intentarlo en breve.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'La solicitud a la inteligencia artificial falló por un motivo que no pudimos identificar. Vuelva a intentarlo; si el problema persiste, comuníquese con soporte técnico con los detalles a continuación.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'El proveedor de IA respondió en un formato que este complemento no pudo leer. Inténtelo de nuevo; si el problema persiste, elija otro modelo o póngase en contacto con el servicio de asistencia.','Custom (OpenAI-compatible)'=>'Personalizado (compatible con OpenAI)','Save a key for this provider first.'=>'Guarda primero una clave para este proveedor.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Su clave funciona, pero el proveedor no incluye ningún modelo de texto para ella. Añada uno usted mismo a continuación.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Conectado. %1$s respondió usando %2$s. Sus funciones de IA están listas para usar.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Su rol de usuario no tiene permitido usar IA en este sitio. Consulte a un administrador.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Este sitio ha alcanzado su límite mensual de gasto en IA. Un administrador puede aumentarlo en la configuración de IA.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Este sitio ha alcanzado su límite mensual de solicitudes de IA. Un administrador puede aumentarlo en la configuración de IA.','Usage and cost'=>'Uso y coste','The log, limits and role permissions apply to AI used through: %s.'=>'El registro, los límites y los permisos de rol se aplican a la IA utilizada a través de: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Los costos son aproximados, calculados a partir de los precios publicados; un modelo sin precio conocido cuenta como cero.','This month: %1$s requests, about %2$s.'=>'Este mes: %1$s solicitudes, aproximadamente %2$s.','When'=>'Cuándo','Who'=>'Quién','Used for'=>'Utilizado para','Model'=>'Modelo','Tokens in / out'=>'Tokens de entrada / salida','About'=>'Acerca de','Result'=>'Resultado','No AI requests have been made yet.'=>'Todavía no se ha realizado ninguna solicitud de IA.','Done'=>'Hecho','Limits and permissions'=>'Límites y permisos','Monthly spending limit (US dollars)'=>'Límite de gasto mensual (dólares estadounidenses US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Déjalo vacío para no establecer límites. La IA se detendrá durante el resto del mes una vez que se alcance el coste aproximado.','Monthly request limit'=>'Límite de solicitudes mensuales','Leave empty for no limit.'=>'Déjelo vacío para no establecer límite.','Who may use AI'=>'Quién puede usar la IA','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'No marcar ninguna opción para permitir que todos los usuarios que puedan usar las características del plugin utilicen la IA. Los administradores siempre pueden usarla.','Save limits and permissions'=>'Guardar límites y permisos','Limits and permissions saved.'=>'Límites y permisos guardados.','That language is not one of this site\'s languages.'=>'Ese idioma no es uno de los idiomas de este sitio.','A translation must be the same kind of content as the original.'=>'Una traducción debe ser el mismo tipo de contenido que el original.','Choose one of the site\'s other languages.'=>'Elija uno de los otros idiomas del sitio.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Los scripts de la pantalla de administración no se encuentran en esta copia del plugin. Vuelva a instalarlo desde un paquete publicado.','This screen needs JavaScript.'=>'Esta pantalla necesita JavaScript.','Choose a language'=>'Elija un idioma','Upgrade'=>'Actualizar','Pricing'=>'Precios','Start Trial'=>'Iniciar prueba','Account'=>'Cuenta','Contact Us'=>'Contacto','Affiliation'=>'Afiliación','the kind of softwarePlugin'=>'Plugin','greetingHey %s,'=>'Hola %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Suscríbase para recibir notificaciones por correo electrónico sobre actualizaciones de seguridad y funciones, contenido educativo y ofertas ocasionales, y para compartir información básica sobre el entorno de WordPress. Esto nos ayudará a hacer que %s sea más compatible con su sitio y mejor para hacer lo que usted necesita que haga.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Suscríbase para recibir notificaciones por correo electrónico sobre actualizaciones de seguridad y funciones, contenido educativo y ofertas ocasionales, y para compartir información básica sobre el entorno de WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Si te saltas este paso, ¡no pasa nada! %1$s seguirá funcionando perfectamente.','Allow & Continue'=>'Permitir y continuar','verbSkip'=>'Omitir','Skipping, please wait'=>'Omitiendo, por favor espere','Continue'=>'Continuar','Please wait'=>'Espere por favor','as activating pluginActivating'=>'Activando','This will allow %s to'=>'Esto permitirá a %s','Privacy Policy'=>'Política de privacidad','Terms of Service'=>'Términos de servicio','License Agreement'=>'Acuerdo de licencia','Have a license key?'=>'¿Tiene una clave de licencia?','Activate License'=>'Activar licencia','View Basic Profile Info'=>'Ver información básica del perfil','Your WordPress user\'s: first & last name, and email address'=>'Nombre y apellido de su usuario de WordPress y dirección de correo electrónico','View Basic Website Info'=>'Ver información básica del sitio web','Homepage URL & title, WP & PHP versions, and site language'=>'URL y título de la página principal, versiones de WP y PHP, e idioma del sitio','View Basic %s Info'=>'Ver información básica de %s','Current %s & SDK versions, and if active or uninstalled'=>'Versiones actuales de %s y del SDK, y si está activo o desinstalado','Newsletter'=>'Boletín','Updates, announcements, marketing, no spam'=>'Actualizaciones, anuncios, marketing, sin spam','View Diagnostic Info'=>'Ver información de diagnóstico','WordPress & PHP versions, site language & title'=>'Versiones de WordPress y PHP, idioma y título del sitio','View Plugins & Themes List'=>'Ver lista de plugins y temas','Names, slugs, versions, and if active or not'=>'Nombres, slugs, versiones y si están activos o no','optional'=>'opcional','Never miss an important update'=>'No se pierda ninguna actualización importante','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Hemos introducido esta opción de consentimiento para que nunca se pierda ninguna actualización importante y para ayudarnos a hacer que %s sea más compatible con su sitio y más eficaz para cumplir con lo que necesita.','Thank you for updating to %1$s v%2$s!'=>'¡Gracias por actualizar a %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'El prefijo debe tener entre 1 y 8 letras minúsculas o dígitos, comenzar con una letra y no debe coincidir con el nombre del plugin.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" no es un código de idioma. Utilice una configuración regional de WordPress como fr_FR o de_DE.','List at least one language.'=>'Enumere al menos un idioma.','You are not allowed to translate this item.'=>'No tiene permiso para traducir este elemento.','This item already has a version in that language.'=>'Este elemento ya tiene una versión en ese idioma.','That translation engine is not available on this site.'=>'Ese motor de traducción no está disponible en este sitio.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Los motores diferentes por idioma, el respaldo automático y los límites de gasto son funciones de Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'Cada idioma debe ser uno de los idiomas del sitio, con un motor disponible.','The fallback list may only name available engines.'=>'La lista de respaldo solo puede nombrar motores disponibles.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Un límite mensual es una cantidad en US dólares, cero o más, para un motor disponible.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Las traducciones preferidas y el tono por idioma son funciones de Tranzly Pro. La lista de términos que no deben traducirse es gratuita.','Glossary entries must be grouped by one of the site\'s languages.'=>'Las entradas del glosario deben agruparse por uno de los idiomas del sitio.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'El tono se configura por idioma del sitio: nivel de formalidad predeterminado (más o menos) e instrucciones opcionales.','The value for %s is not one of the allowed choices.'=>'El valor para %s no es una de las opciones permitidas.','The background queue is not available on this site.'=>'La cola en segundo plano no está disponible en este sitio.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Un trabajo de traducción se ejecuta como la persona que lo inicia, por lo que el usuario debe haber iniciado sesión.','There is nothing you are allowed to translate in that selection.'=>'No hay nada que tengas permitido traducir en esa selección.','That item is not part of a translation job.'=>'Ese elemento no forma parte de un trabajo de traducción.','You are not allowed to change that translation.'=>'No tiene permitido cambiar esa traducción.','This item\'s group already has a %1$s version (#%2$d).'=>'El grupo de este elemento ya tiene una versión %1$s (#%2$d).','An item cannot be its own translation.'=>'Un elemento no puede ser su propia traducción.','That item is already a translation of something else. Unlink it first.'=>'Ese elemento ya es una traducción de otra cosa. Desvínculelo primero.','The translation link could not be saved.'=>'No se pudo guardar el enlace de traducción.','That text cannot be translated here.'=>'Ese texto no se puede traducir aquí.','That media text cannot be translated here.'=>'Ese texto multimedia no se puede traducir aquí.','A translation can be published or kept as a draft.'=>'Una traducción se puede publicar o guardar como borrador.','You are not allowed to publish this kind of content.'=>'No tienes permitido publicar este tipo de contenido.','This item is already written in that language.'=>'Este elemento ya está escrito en ese idioma.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Esta traducción fue editada por una persona (o importada), por lo que está protegida. Desbloquéela para volver a traducirla.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'No se ha configurado ningún motor de traducción todavía. Añada una clave para uno en Tranzly → Engines.','That translation engine is not set up yet: add its key first.'=>'Ese motor de traducción aún no está configurado: añada su clave primero.','The same text is being translated by another job right now; this item will use that answer.'=>'El mismo texto está siendo traducido por otra tarea en este momento; este elemento utilizará esa respuesta.','No translation engine could take this item.'=>'Ningún motor de traducción pudo procesar este elemento.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'El motor no devolvió una traducción para todas las partes de este elemento. No se realizaron cambios.','AI model'=>'Modelo de IA','AI model (%1$s %2$s)'=>'Modelo de IA (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s presenta problemas en este momento. Inténtelo de nuevo en breve o utilice otro motor.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Su sitio no pudo conectarse a %s. Compruebe que pueda realizar conexiones salientes y vuelva a intentarlo.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s no aceptó su clave de API. Compruebe la clave en Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Su cuenta de %s ha agotado su cuota o saldo. Recárguela con ellos o utilice otro motor.','%s asked us to slow down. It will be tried again automatically.'=>'%s nos ha pedido que vayamos más lento. Se intentará de nuevo automáticamente.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Este texto es demasiado largo para %s de una vez. Divide el contenido o utiliza otro motor.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s se ha negado a traducir este contenido. Pruebe con otro motor o tradúzcalo manualmente.','%s does not translate this language. Choose another engine for it.'=>'%s no traduce este idioma. Elija otro motor para él.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'Se ha alcanzado el límite de gasto de este mes para %s, por lo que no se ha enviado nada más. Aumente el límite en Tranzly → Engines o espere hasta el próximo mes.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'La traducción con %s falló por un motivo que Tranzly no pudo identificar. Los detalles se muestran a continuación.','An engine id must be lowercase letters, digits and hyphens.'=>'Un identificador de motor debe constar exclusivamente de letras minúsculas, números y guiones.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Creado por Neil Lock, director general de Zinn Digital® Ltd','Version %s'=>'Versión %s','Tranzly website'=>'Sitio web de Tranzly','Zinn Digital® website'=>'sitio web de Zinn Digital®','Settings saved.'=>'Configuración guardada.','See the Pro plans and pricing'=>'Consulte los planes y precios Pro','Languages'=>'Idiomas','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'El primer idioma es aquel en el que está escrito su contenido. Los visitantes cambian mediante el bloque selector de idiomas.','(default)'=>'(predeterminado)','Locale code'=>'Código de configuración regional','For example fr_FR'=>'Por ejemplo fr_FR','Name (optional)'=>'Nombre (opcional)','For example Français'=>'Por ejemplo Français','Add language'=>'Añadir idioma','Front-end output'=>'Salida del front-end','Class name prefix'=>'Prefijo de nombre de clase','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Cada nombre de clase que el complemento imprime en sus páginas comienza con este prefijo, para que las páginas no revelen qué complemento las creó. De 1 a 8 letras minúsculas o dígitos, comenzando con una letra.','Beta updates'=>'Actualizaciones en versión beta','This site receives beta versions as updates.'=>'Este sitio recibe versiones beta como actualizaciones.','This site receives stable versions only.'=>'Este sitio recibe únicamente versiones estables.','Change this on the Account page'=>'Cambie esto en la página de Cuenta','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Las versiones beta se ofrecen a instalaciones Pro con licencia que estén conectadas a su cuenta. Una vez conectadas, puede unirse desde la página de la cuenta.','Save settings'=>'Guardar configuración','First engine that is set up'=>'Primer motor configurado','Key saved. It is stored encrypted and never shown again.'=>'Clave guardada. Se almacena cifrada y no se vuelve a mostrar.','Engine settings saved.'=>'Ajustes de motor guardados.','Glossary saved.'=>'Glosario guardado.','Your keys'=>'Sus claves','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Tranzly llama a los servicios de traducción con su propia cuenta. Las claves se almacenan de forma cifrada en su base de datos y solo se envían al servicio al que pertenecen. Las claves de los modelos de IA se configuran en los ajustes de IA.','%s API key'=>'Clave de API de %s','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Guardado: %s. Introduzca una nueva clave para reemplazarlo, o guarde un campo vacío para eliminarlo.','No key saved.'=>'No hay ninguna clave guardada.','Azure region (leave empty for a global resource)'=>'Región de Azure (dejar en vacío para un recurso global)','Save key'=>'Guardar clave','Check my DeepL usage'=>'Comprobar mi uso de DeepL','%1$s of %2$s characters used this billing period.'=>'%1$s de %2$s caracteres utilizados en este período de facturación.','Which engine translates'=>'¿Qué motor traduce','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'No se ha configurado ningún motor todavía. Guarda una clave arriba (o configura un modelo de IA) para empezar a traducir.','Default engine'=>'Motor predeterminado','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Un motor diferente por idioma, la alternancia automática y los límites de gasto mensual son funciones de Tranzly Pro.','Engine for %s'=>'Motor para %s','The default engine'=>'El motor predeterminado','If an engine fails or reaches a limit, try these next, in this order'=>'Si un motor falla o alcanza un límite, pruebe con los siguientes en este orden','Monthly spending caps'=>'Límites de gasto mensual','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Cuando un motor alcanza su límite, no se le envía nada más hasta el mes siguiente y el informe de traducción fallida indica el motivo. Déjelo vacío si no desea establecer un límite.','%1$s (spent this month: $%2$s)'=>'%1$s (gastado este mes: $%2$s)','Save caps'=>'Guardar mayúsculas','Glossary and words never translated'=>'Glosario y palabras que nunca se traducen','Never translate these words (one per line)'=>'Nunca traduzcas estas palabras','Brand and product names stay exactly as they are, with every engine.'=>'Los nombres de marcas y productos se mantienen exactamente igual en todos los motores.','Preferred translations and tone per language are Tranzly Pro features.'=>'Las traducciones preferidas y el tono por idioma son características de Tranzly Pro.','Preferred translations (one per line: term = translation)'=>'Traducciones preferidas (una por línea: término = traducción)','Formality'=>'Formalidad','Default'=>'Predeterminado','Formal'=>'Formal','Informal'=>'No oficial','Style instructions (audience, brand voice)'=>'Instrucciones de estilo (audiencia, tono de marca)','Save glossary'=>'Guardar glosario','Job started with %d translations to do. It runs in the background: you can close this page.'=>'Trabajo iniciado con %d traducciones pendientes. Se ejecuta en segundo plano: puede cerrar esta página.','Queued again.'=>'Vuelto a poner en cola.','Running'=>'En ejecución','Finished'=>'Finalizado','Cancelled'=>'Cancelado','Translate in the background'=>'Traducir en segundo plano','Set up a translation engine in the Engines tab first.'=>'Configure primero un motor de traducción en la pestaña Motores.','Translate every'=>'Traducir todo','Into'=>'Hacia','With'=>'Con','Each language’s own engine'=>'El motor propio de cada idioma','Publish the translations (otherwise they are saved as drafts)'=>'Publique las traducciones (de lo contrario se guardarán como borradores)','Estimate the cost'=>'Estimar el costo','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d entradas, %2$s caracteres. El precio de este motor no se conoce de antemano.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d publicaciones, %2$s caracteres: aproximadamente $%3$s en su propia cuenta.','Start translating'=>'Empezar a traducir','Jobs'=>'Trabajos','No translation jobs yet.'=>'No hay trabajos de traducción pendientes.','Job %1$d — %2$s'=>'Trabajo %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d de %2$d traducidos, %3$d con errores, %4$d omitidos (protegidos o ya en ese idioma)','Stop this job'=>'Detener esta tarea','See what failed and why'=>'Vea qué falló y por qué','Content'=>'Contenido','Language'=>'Idioma','What went wrong'=>'Qué salió mal','Fix it'=>'Corregir','Details'=>'Detalles','Retry with'=>'Reintentar con','The same engine'=>'El mismo motor','Retry'=>'Reintentar','Translate by hand'=>'Traducir manualmente','Languages and settings'=>'Idiomas y configuración','Engines'=>'Motores','Translation jobs'=>'Trabajos de traducción','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Añade un segundo idioma en Tranzly dentro del menú de administración y el selector aparecerá aquí.','Switcher'=>'Selector','Accessible label'=>'Etiqueta accesible','block titleLanguage switcher'=>'Selector de idioma','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Enlaces a esta página en cada uno de los idiomas del sitio. No muestra nada hasta que se enumeran dos o más idiomas.','block keywordlanguage'=>'idioma','block keywordswitcher'=>'Selector','block keywordtranslation'=>'traducción']];